function deferPanel<P extends object>(load: () => Promise<{default: ComponentType<P>}>) {
  const Component = lazy(load);
  return function DeferredPanel(props: P) {
    return <Suspense fallback={null}>{createElement(Component,props as any)}</Suspense>;
  };
}
