 async function openWhatsapp(){if(!contactEdit||contacts.some(x=>x.caseId===contactEdit.c.id&&x.status==='sent'))return;const s=student(contactEdit.c.studentId);if(!s)return;const p=phoneFor(s);if(!/^\d{9,15}$/.test(p)){setError('رقم ولي الأمر غير صالح. حدّثه في إدارة الطلاب.');return;}const w=window.open('about:blank','_blank');if(w)w.opener=null;const result=await mutate('contact',{caseId:contactEdit.c.id,status:'opened',message:contactEdit.message});if(!result){w?.close();return;}const url='https://wa.me/'+p+'?text='+encodeURIComponent(contactEdit.message);if(w)w.location.href=url;else window.location.href=url;}
 function exportCsv(rows:Case[]){const safe=(s:string)=>'"'+(/^[=+@\-\t\r]/.test(s)?"'":'')+s.replace(/"/g,'""')+'"';const out=[['الطالب','الصف','الفصل','التاريخ والوقت','نوع الحالة','التفاصيل','الإجراء','مدخل البيانات','المتابعة','النتيجة','التواصل','بيانات الحالة الإضافية'],...rows.map(c=>{const s=student(c.studentId);return[s?.name||'',s?.grade||'',s?.classroom||'',stamp(c.occurredAt,language),c.type,c.details,c.action,c.actor,c.followStatus==='open'?'قيد المتابعة':c.followStatus==='done'?'مغلقة':'لا تحتاج',c.outcome,contacts.filter(x=>x.caseId===c.id).map(x=>x.status==='sent'?'إرسال مؤكد يدويًا':'فتح واتساب').join('،'),summarizeExtra(c.type,readExtra(c.extra))];})].map(r=>r.map(safe).join(',')).join('\r\n');saveFile('shuoon-report-'+today()+'.csv','\uFEFF'+out,'text/csv;charset=utf-8');}
 async function backup(){setBusy(true);setError('');try{const v:any=await requestApi('/api/backup');saveFile('sijillati-backup-'+today()+'.json',JSON.stringify(v,null,2));setNotice('تم تنزيل نسخة احتياطية حديثة من السجلات المحفوظة');}catch(e){if(e instanceof ApiResponseError)setNeedsLogin(e.reauthenticate);setError(e instanceof Error?e.message:'تعذر إنشاء النسخة الاحتياطية');}finally{setBusy(false);}}
 async function restore(file:File){if(file.size>10000000){setError('حجم الملف أكبر من 10 ميجابايت');return;}try{const v=JSON.parse(await file.text());if(v.format!=='shuoon-independent-v1')throw new Error('اختر نسخة احتياطية صادرة من هذا البرنامج');if(!confirm(ui('سيتم إضافة السجلات المفقودة فقط دون استبدال بياناتك الحالية. هل تريد المتابعة؟')))return;const r=await mutate('restore',v);if(r){try{const extra:any=await requestApi('/api/school-work',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({op:'restore',data:v})});let careAdded=0;if(allowCare&&(v.studentCare||v.careIntake)){const care:any=await requestApi('/api/student-care',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({op:'restore',data:v})});careAdded=care.added;}setNotice(`${ui("السجلات المضافة")}: ${r.added+extra.added+careAdded}`);}catch{setError(ui('اكتملت استعادة السجلات الأساسية، وتعذر استكمال بعض السجلات الإضافية أو بيانات الرعاية. أعد المحاولة؛ لن تتكرر السجلات.'));}};}catch(e){if(e instanceof ApiResponseError)setNeedsLogin(e.reauthenticate);setError(e instanceof Error?e.message:'ملف غير صالح');}}
 const sentCaseIds=new Set(contacts.filter(c=>c.status==='sent').map(c=>c.caseId));
 const todayPending=todays.filter(c=>!sentCaseIds.has(c.id)),todaySent=todays.filter(c=>sentCaseIds.has(c.id)),todayVisible=todayNotification==='sent'?todaySent:todayNotification==='pending'?todayPending:todays;
 function caseCard(c:Case){const s=student(c.studentId),history=contacts.filter(x=>x.caseId===c.id),notified=sentCaseIds.has(c.id);return <article className="case-card" key={c.id}><div className={'case-symbol tone-'+TYPES.indexOf(c.type)}>{c.type===TYPES[3]?<Leaf size={20}/>:c.type===TYPES[0]?<Clock size={20}/>:<FileText size={20}/>}</div><div className="case-content"><div className="case-head"><button className="text-button student-name" onClick={()=>setProfile(c.studentId)}>{s?.name||ui('طالب مؤرشف')}</button><span className={'tag tone-'+TYPES.indexOf(c.type)}>{ui(c.type)}</span>{c.followStatus==='open'&&<span className="tag amber"><UiText text={"قيد المتابعة"}/></span>}{c.followStatus==='done'&&<span className="tag tone-3"><UiText text={"تمت المتابعة"}/></span>}{notified&&<span className="tag tone-3"><UiText text={"تم إشعار ولي الأمر"}/></span>}</div><p className="muted small">{s?.grade} <UiText text={" • فصل "}/>{s?.classroom} <span className="sep">|</span> {stamp(c.occurredAt,language)}</p><p className="details">{c.details}</p>{extraRows(c.type,readExtra(c.extra)).length>0&&<dl className="case-extra-summary">{extraRows(c.type,readExtra(c.extra)).map(([label,value])=><div key={label}><dt>{ui(String(label))}</dt><dd>{value}</dd></div>)}</dl>}<p className="small"><strong><UiText text={"الإجراء: "}/></strong>{c.action}</p>{c.outcome&&<p className="outcome"><UiText text={"نتيجة المتابعة: "}/>{c.outcome}</p>}<div className="case-foot"><span className="muted small"><UiText text={"سجّلها: "}/>{c.actor} • {stamp(c.createdAt,language)}{c.updatedAt&&<><br/><UiText text={"آخر تعديل: "}/>{stamp(c.updatedAt,language)} • {c.updatedBy}</>}</span><div className="actions"><button className="ghost" onClick={()=>setEvidenceCase(c)}><FileText size={14}/>{ui('شواهد الحالة')}</button><button className="ghost" onClick={()=>{setScheduledCaseId(c.id);go('desk');}}>{ui('تحديد موعد متابعة')}</button><button className="ghost" onClick={()=>setViewCase(c)}><Eye size={14}/><UiText text={"عرض"}/></button><button className="ghost" onClick={()=>editCase(c)}><Pencil size={14}/><UiText text={"تعديل"}/></button>{mainAdmin&&<button className="ghost danger" disabled={busy} onClick={()=>setDeleteCase(c)}><Trash2 size={14}/><UiText text={"حذف"}/></button>}{printKind(c.type)&&<button className="ghost" onClick={()=>openPrint(c)}><FileText size={14}/>{ui(printLabel(c.type))}</button>}{s?.phone&&!notified&&<button className="ghost" disabled={busy} onClick={()=>setContactEdit({c,message:messageFor(c,s)})}><Phone size={14}/><UiText text={"إشعار واتساب"}/></button>}{c.followStatus!=='done'&&<button className="ghost" disabled={busy} onClick={()=>{setFollowEdit(c);setOutcome(c.outcome);}}><Check size={14}/> <UiText text={" متابعة"}/></button>}</div></div>{history.length>0&&<div className="contact-history small">{history.map(x=><div key={x.id}>{x.status==='sent'?ui("✓ إرسال أكده المستخدم"):ui("↗ تم فتح واتساب")} • {stamp(x.createdAt,language)} • {x.actor}</div>)}</div>}</div></article>}
 function empty(title:string,text:string,action?:()=>void,label='إضافة طالب'){return <div className="empty"><div className="empty-icon"><GraduationCap size={32}/></div><h3>{ui(title)}</h3><p>{ui(text)}</p>{action&&<button className="primary" onClick={action}><Plus size={16}/>{ui(String(label))}</button>}</div>}
 function field(label:string,node:React.ReactNode){return <label className="field" data-field-tone={fieldTone(label)}><span>{ui(String(label))}</span>{node}</label>}
